@RestController
@RequestMapping("/api/v1/users")
public class UserController {

    @GetMapping("/{id}")
    public ResponseEntity<UserDTO> getUser(@PathVariable Long id) {
        // GET: Safe and idempotent retrieval
        return userService.findById(id)
                .map(ResponseEntity::ok)
                .orElse(ResponseEntity.notFound().build());
    }

    @PostMapping
    public ResponseEntity<UserDTO> createUser(@RequestBody UserCreateDTO dto) {
        // POST: Not idempotent, creates a new resource
        UserDTO created = userService.save(dto);
        return ResponseEntity.status(HttpStatus.CREATED).body(created);
    }

    @PutMapping("/{id}")
    public ResponseEntity<UserDTO> replaceUser(@PathVariable Long id, @RequestBody UserUpdateDTO dto) {
        // PUT: Idempotent total replacement
        UserDTO updated = userService.fullyUpdate(id, dto);
        return ResponseEntity.ok(updated);
    }

    @PatchMapping("/{id}")
    public ResponseEntity<UserDTO> patchUser(@PathVariable Long id, @RequestBody Map<String, Object> updates) {
        // PATCH: Non-idempotent partial update
        UserDTO patched = userService.partiallyUpdate(id, updates);
        return ResponseEntity.ok(patched);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteUser(@PathVariable Long id) {
        // DELETE: Idempotent removal
        userService.delete(id);
        return ResponseEntity.noContent().build();
    }
}
